import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 17
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for row in reader:
        if row:
            records.append(row)

    if not records:
        return {"columns": [], "rows": []}

    threshold = max(1, expected_width - 1)
    candidates = [
        (index, row)
        for index, row in enumerate(records)
        if len(row) >= threshold
    ]

    if candidates:
        header_index, header = max(
            candidates,
            key=lambda item: (
                sum(any(char.isalpha() for char in cell) for cell in item[1]),
                sum(sum(char.isalpha() for char in cell) for cell in item[1]),
                len(item[1]),
                -item[0],
            ),
        )
    else:
        header_index, header = 0, records[0]

    width = max(expected_width, len(header))
    for row in records[header_index + 1:]:
        width = max(width, len(row))

    columns = list(header)
    while len(columns) < width:
        columns.append("Extra column {}".format(len(columns) + 1))

    rows = []
    for row in records[header_index + 1:]:
        rows.append((row + [""] * width)[:width])

    return {"columns": columns, "rows": rows}
